    t69 = _conv2d(t68, c33, c21, stride=(1, 1), dilation=(1, 1), padding='SAME', act='RELU')
    t70 = _conv2d(t69, c34, c22, stride=(1, 1), dilation=(1, 1), padding='SAME', act='RELU')
    t71 = _conv2d(t70, c35, c52, stride=(1, 1), dilation=(1, 1), padding='VALID', act='NONE')
    t72 = _act(jnp.add(t71, t68), 'RELU6')
    t73 = _conv2d(t72, c36, c53, stride=(2, 2), dilation=(1, 1), padding='SAME', act='NONE')
    t74 = _conv2d(t72, c37, c23, stride=(1, 1), dilation=(1, 1), padding='SAME', act='RELU')
    t75 = _conv2d(t74, c38, c24, stride=(2, 2), dilation=(1, 1), padding='SAME', act='RELU')
    t76 = _conv2d(t75, c39, c54, stride=(1, 1), dilation=(1, 1), padding='VALID', act='NONE')
    t77 = _act(jnp.add(t76, t73), 'RELU6')
    t78 = _conv2d(t77, c40, c13, stride=(1, 1), dilation=(1, 1), padding='SAME', act='RELU')
    t79 = _conv2d(t78, c41, c14, stride=(1, 1), dilation=(1, 1), padding='SAME', act='RELU')
    t80 = _conv2d(t79, c42, c55, stride=(1, 1), dilation=(1, 1), padding='VALID', act='NONE')
    t81 = _act(jnp.add(t80, t77), 'RELU6')
    t82 = _conv2d(t81, c43, c15, stride=(1, 1), dilation=(1, 1), padding='SAME', act='RELU')
    t83 = _conv2d(t82, c44, c16, stride=(2, 2), dilation=(1, 1), padding='SAME', act='RELU')
    t84 = _conv2d(t83, c45, c56, stride=(1, 1), dilation=(1, 1), padding='VALID', act='NONE')
    t85 = _conv2d(t81, c46, c57, stride=(2, 2), dilation=(1, 1), padding='SAME', act='NONE')
    t86 = _act(jnp.add(t84, t85), 'RELU6')
    t87 = _conv2d(t86, c47, c17, stride=(1, 1), dilation=(1, 1), padding='SAME', act='RELU')
    t88 = _conv2d(t87, c48, c19, stride=(1, 1), dilation=(1, 1), padding='SAME', act='RELU')
    t89 = _conv2d(t88, c49, c58, stride=(1, 1), dilation=(1, 1), padding='VALID', act='NONE')
    t90 = _act(jnp.add(t89, t86), 'RELU6')
    t91 = jnp.reshape(t90, (-1, 512))
    t92 = _fc(t91, c59, c20, keep_num_dims=False, act='RELU')
    t93 = _fc(t92, c26, c5, keep_num_dims=False, act='NONE')
    t94 = _fc(t92, c27, c6, keep_num_dims=False, act='NONE')
    t95 = jnp.reshape(t93, (18, 2))
    t96 = jnp.reshape(t94, (56, 2))
    t97 = jnp.reshape(x2, (56, 2))
    t98 = jnp.add(t97, t96)
    t99 = jnp.reshape(x1, (18, 2))
    t100 = jnp.add(t99, t95)

    return (t98, t100,)
